window.VD=window.VD||{};window.VD["audi/tt-8j"]={"tt-8j-facelift-activate-daytime-running-lights-in-odb":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose</strong>: to activate/deactivate the daytime running lights (DRL) on the on-board computer.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then <strong>“<strong>Long Coding Helper</strong>”.</strong></p>\n<p><strong>5</strong> – Select Byte<strong> 22 </strong>:</p>\n<p>Bit<strong> 1 </strong>: Check<em> <strong>“Daytime Running Lights (DRL) Switchable via Menu”.</strong> </em> </p>","tt-8j-facelift-aps-radar-display-on-rns-e-screen":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose </strong>: to activate the display of Audi Parking System radars on the RNS-E screen.  </p>\n<p><strong><em>WARNING: requires RNS-E version 193 and rear + front radars  </em></strong></p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>37 – Navigation</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Coding- 07</strong>”.  </p>\n<p><strong>5</strong> –  <em>Add <strong>2</strong> to the 3rd digit. (e.g. replace <strong>xx0xxxx</strong>by <strong>xx2xxxx</strong>) </em></p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click <strong>“10 – Parking Assistance</strong>,” then <strong> “Security -16</strong>” (code 71679)<br/><br/><strong>4 </strong>– Click <strong>“Coding – 07</strong>,” then<strong>“Long Coding</strong> Helper”</p>\n<p><strong>5</strong> – <em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>4</strong>: Check the “Optical illustration active” box</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/RNSeaps-141b4bc9.webp\"/></figure>","tt-8j-facelift-comfort-turn-signal":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose:</strong> to set the number of flashes for the “Comfort flashing” option.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4 – </strong> Click “<strong>Adaptation – 10</strong>.”</p>\n<p><strong>5 </strong>– Select<strong>“Comfort Turn Signal”</strong> from the drop-down list </p>\n<p>Choose a value between 1 and 5 for the number of flashes</p>","tt-8j-facelift-corner-lights-activation":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose</strong>: Activating the <strong>turn signals</strong> causes the fog light on the side toward which you’re turning the steering wheel to turn on when traveling at speeds below 50 km/h. This feature is also known as “cornering lights.” Once this feature is activated on your Audi TT, the fog light on the side of the turn you’re making will turn on! It’s super handy on narrow roads or in roundabouts.     </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port.<br/><br/><strong></strong> 2 – Turn on the ignition, then launch the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>09 – Power Control Unit</strong>.”</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/4-Activation-des-feux-en-virage-sur-Golf-5-et-6-f4e51c90.webp\"/></figure>\n<p><strong>6</strong> – In the window that appears, select  </p>\n<p><em>Byte 12 ( </em>optional)<br/><em>Bit 4: Check “Cornering Light Activation Time Limited”</em></p>\n<p><em>Byte 14: </em><br/><em>Bit 7: Check “Cornering Lights via Front Fog Lights active”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5-Activation-de-la-fonction-Cornering-Lights-via-F-255e876b.webp\"/></figure>\n<p><strong>7</strong> – After completing this step, click on the “Exit” menu<br/>, then click “OK.”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6-Activation-de-la-fonction-Cornering-Lights-via-F-2a08cc40.webp\"/></figure>","tt-8j-facelift-deactivate-automatic-spoiler-folding":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose</strong>: to deactivate automatic spoiler folding when the spoiler has been deployed manually.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>09 – Cent. Elect.</strong>”. Switch on the ignition and run the VCDS program.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/> 5 – Choose <em>Byte <strong>13</strong>: </em><br/><em>Bit <strong>6</strong>: Uncheck “Rear Spoiler Automatic Lowering after Manual Raising inactive”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8P0-907-063-B_Module09_Byte13-b06cb7b1.webp\"/></figure>","tt-8j-facelift-deactivate-spoiler":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose</strong>: to disable spoiler operation. If you code the spoiler deployed or closed, it will be locked in the position after coding! Perfect for mounting a fixed tuning spoiler.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>09 – Cent. Elect.</strong>”. Switch on the ignition and run the VCDS program.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/> 5 – Choose <em>Byte <strong>10</strong>: </em><br/><em>Bit <strong>3</strong>: Uncheck “Rear Spoiler Installed”.</em></p>","tt-8j-facelift-deactivating-the-windshield-washer-indicator":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi TT 8J facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose </strong>: to deactivate the windshield washer indicator on the ODB (on-board computer).  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07 </strong>”.  </p>\n<p><strong>5</strong> – <em>Subtract <strong>5 from the </strong>last coding digit (00xxxx<strong>?</strong>)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-A3-8P-ed05618a.webp\"/></figure>\n<p>Example: 0000148 -&gt; 0000143</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/laveglaceaudia38p-d44c3cb7.webp\"/></figure>","tt-8j-facelift-disable-plate-light-control-odb-led-error":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose:</strong> Disables license plate light control. Useful when installing LED bulbs without resistance or for error prevention.   </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Bytes <strong>23 </strong>:  </p>\n<p>Bit <strong>6</strong>: Uncheck: “Lamp Monitoring (Cold) License Plate Lamps Active”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/led_plaque5-odt_147-d36567c5.webp\"/></figure>\n<p>And <em>Byte <strong>17</strong>: </em><br/><em>Bit <strong>7: </strong> Uncheck “License Plate Light w/o Pulse Width Modulation (PWM) [LED Light]”.</em></p>","tt-8j-facelift-flash-mode-lights-during-emergency-braking":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose</strong>: activates the brake/turn signal lights in flash mode during emergency braking.  </p>\n<p><strong>Procedure: </strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>16</strong>: </em><br/><em>Bit <strong>1</strong>: Check “Emergency Brake Flashing via Brake Light active” (to activate brake lights)</em><br/><em>Bit <strong>2</strong>: Check “Emergency Brake Flashing via Turn Signal active” (to activate turn signals)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/emergencybreakg6-7e26fa37.webp\"/></figure>","tt-8j-facelift-gear-display-on-odb":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi TT 8J facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose:</strong> to activate the gear display on the on-board computer (for manual gearboxes).   </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on ” <strong>10 – Adaptation</strong> </p>\n<p><strong>5</strong> – Select<strong> Channel 36</strong> <em>“Special Functions”</em><br/><em>Add <strong>+1</strong> to the existing value as specified in the tooltip (?xx).</em></p>\n<p><em><em>Example:</em></em> <em>original value 000: change to 100</em></p>\n<p>So excluding S/RS, the only possible value is: 100</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Audi-tt-rapport-4384918e.webp\"/></figure>","tt-8j-facelift-lap-timer":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi TT 8J facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose:</strong> to add the stopwatch to the ODB (on-board computer).  </p>\n<p><strong><em>ATTENTION: Only for TTS and TT Facelift compatible according to meter.</em></strong> </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on ” <strong>10 – Adaptation</strong> </p>\n<p><strong>5</strong> – Select<strong> Channel 36</strong> <em>“Special Functions”</em><br/><em>Add <strong>+1</strong> to the existing value as specified in the bubble (x?x).</em></p>\n<p><em>Example: origin value 01 or 1: change to 11 / origin value 00: change to 10</em> / <em>origin value 000: change to 010</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/11-Tuto-Vagcom-A3-8P-Check-des-Aiguilles-S3-ET-RS3-2ab59919.webp\"/></figure>","tt-8j-facelift-lock-the-rns-es-cd-dvd-eject-button":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi TT 8J facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose</strong>: To lock/unlock the RNS-E’s CD/DVD eject button.  </p>\n<p><em>Protection against theft of your navigation DVD.  </em></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program. <strong><strong>37 – Navigation</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Choose <em><strong>Channel 67</strong> </em>then set the value to <strong>255</strong> <em>(Eject Button locked i.e. (Rental Car))</em></p>\n<p><em>Restart RNS-E.</em></p>\n<p>To eject the CD/DVD, set the value to <strong>0</strong> for normal use of the button, or <strong>1</strong> to eject it immediately.  </p>","tt-8j-facelift-locking-unlocking-beeps":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose</strong>: Enables vehicle lock/unlock confirmation with beeps (alarm) and adds beep selection menu to ODB (MFA).  </p>\n<p><strong>Procedure: </strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>05 </strong>: </em><br/><em>Bit <strong>1</strong>: Check “Locking Confirmation via Horn active”.</em><br/><em>Bit <strong>2</strong>: Uncheck “Horn Confirmation Adaptation blocked (Adaptation Channel 010/011 &amp; MFA+/FIS)”.</em><br/><em>Bit <strong>4</strong>: Check “Unlocking Confirmation via Horn active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/horng6-2ffc7685.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/horng62-14ab4a90.webp\"/></figure>","tt-8j-facelift-maintain-decrease-drl-with-turn-signals":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose:</strong> to maintain or reduce the intensity of the daytime running lights (DRL) with the indicators.  </p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>15</strong>: </em><br/><em>Bit <strong>3</strong>: “Daytime Running Light (DRL) inactive with Turn Signals active”.</em></p>\n<p>Uncheck to maintain intensity or Check to lower intensity.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audittled-f128febf.webp\"/></figure>","tt-8j-facelift-modifying-the-rns-e-start-screen":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose </strong>: to change the screen display at RNS-E start-up.  </p>\n<p><strong><em><em>CAUTION (Some RNS-E settings are directly related to the selected model. It is not recommended to change the vehicle model (Line 1)). </em> </em></strong></p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“37 – Navigation</strong>” .<br/><br/><strong>4 </strong>– Click on<strong>“Codage- 07</strong>”.</p>\n<p><strong>5</strong> – Change the 2nd digit to the desired model. (ex: replace<strong>02xxxxx</strong>by<strong>01xxxxx</strong>to display the Lamborghini logo on an A3) </p>\n<p>– 1 Lamborghini Galardo<br/>– 2 <em>Audi A3 (8P)</em><br/>– 3 Audi A4 (8E) or Seat Exeo (3R)<br/>– 4 Audi A4 Cabriolet (8H)<br/>– 5 Audi A6 (4B)<br/>– 6 Audi TT (8J)<br/>– 7 Audi R8 (42)</p>\n<p><strong>Line 2:</strong><br/><br/> 3 – Click on “<strong>Select”</strong>, then click on<strong>“37 – Navigation</strong>” .<br/><br/> 4<strong>– </strong>Click on<strong>“Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 18</strong> (Start Screen) then set the value according to the desired display. <br/><br/>– 0 Standard<br/>– 1 Audi S3 (8P)<br/>– 2 Audi S4 (8E)<br/>– 3 Audi RS4, (8E)<br/>– 4 Audi TT (8J)<br/>– 5 Audi R8 (42)<br/>– 7 Audi TT S (8J)<br/>– 8 Audi TT RS (8J)<br/>– 9 Audi R8 GT (<em>42</em>)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8P0-035-193-G_Module37_Adaptation_Channel18-4f78df82.webp\"/></figure>","tt-8j-facelift-needle-check":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi TT 8J facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose:</strong> activates needle sweep when the car is started. (Needle Sweep)   </p>\n<p><strong><em>ATTENTION: Only for TTS and TT Facelift compatible according to meter.  </em></strong></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on ” <strong>10 – Adaptation</strong> </p>\n<p><strong>5</strong> – Select<strong> Channel 36</strong> <em>“Special Functions”</em><br/><em>Add <strong>+1</strong> to the existing value as indicated in the bubble (xx?).</em></p>\n<p><em><em>Example: origin value 00 or 0: change to 01 or 1 / origin value 10: change to 11</em></em> / <em>origin value 000 : change to 001</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/11-Tuto-Vagcom-A3-8P-Check-des-Aiguilles-S3-ET-RS3-2ab59919.webp\"/></figure>","tt-8j-facelift-remove-belt-alarm":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose:</strong> to suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt (for models from 2010).  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4 </strong>– Click on “<strong>Coding – 07 </strong>”.  </p>\n<p><em>Put<strong> 0</strong> in the penultimate digit of the code (00xxx<strong>?</strong>x)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-A3-8P-ed05618a.webp\"/></figure>\n<p>Example: 0000143 -&gt; 0000103</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","tt-8j-facelift-speed-limit-display-rns-e":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi TT 8J facelift\" decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose </strong>: to display the speed limit on the RNS-E navigation screen.  </p>\n<p><strong><em>ATTENTION: requires RNS-E version 193</em></strong></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong><br/></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on<strong>“37 – Navigation</strong>”.<br/><br/> 4<strong>– </strong>Click on<strong>“Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 17</strong> (Speed Display) then set the value according to the desired display. <br/><br/>Set the value according to the desired display<em><br/>0</em><em>– no option (display disabled)<br/></em> 1<em>– option on, off (speed display)<br/></em> 2<em>– option on, off, 5km/h, 10km/h, 15km/h, 20km/h (speed display + overrun warning)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8P0-035-193-G_Module37_Adaptation_Channel17-6e590288.webp\"/></figure>\n<p><em>Don’t forget to restart the RNS-E, by pressing the power button for more than 40s.</em></p>","tt-8j-facelift-spoiler-lowered-when-locked":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_facelift-477a7d14.webp\"/></figure>\n<p><strong>Purpose</strong>: to lower the spoiler after the doors have been closed centrally.  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port.<br/><br/><strong></strong> 2 – Turn on the ignition, then launch the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Power Control Unit</strong>.”</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>,” then click on “<strong>Long Coding Helper</strong>.”<br/><br/><strong>5</strong> – Select <em>Byte <strong>13</strong>: </em><br/><em>Bit <strong>7</strong>: Uncheck “Rear Spoiler Comfort Lowering via Door Lock active”</em> <em>to disable it</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8P0-907-063-B_Module09_Byte13-b06cb7b1.webp\"/></figure>","tt-8j-activate-advanced-comfort-menu-in-odb":"<p><strong>Purpose:</strong> activates the advanced comfort menu in the on-board computer, activating oil temperature and other functions.  </p>\n<p><em><strong>Modification only possible for vehicles with a 30-byte module.</strong></em> </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte 23: </em><br/><em>Bit 1: Check “</em>Advanced Comfort<em> Menu active”.</em></p>","tt-8j-activate-mood-lighting":"<p><strong>Purpose</strong>: to activate ambient foot lighting while driving. The footwell lights in the MFA appear in the Light &amp; Visibility menu, where brightness can also be adjusted.   </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong> “Long Coding Helper”</strong>.</p>\n<p><strong>5</strong> – Choose <em>Byte <strong>12</strong> </em><br/><em>Check Bit <strong>5</strong></em></p>","tt-8j-activate-turn-signals-in-us-mode":"<p><strong>Purpose:</strong> to activate US indicators. (TT 8J phase 1 only) </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><strong>Byte 7</strong>: Enter value<strong> 32</strong> in <strong>Dec</strong> box<br/>(value in % of intensity, origin: 0)</p>\n<p>Decimal examples shown in yellow in the image:<br/>14 (corresponds to a 20% variation in the indicator lights)<br/>1E (corresponds to a 30% variation in the indicator lights)<br/>28 (corresponds to a 40% variation in the indicator lights)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/3C0-937-049-Q_Module09_Byte7-16502f21.webp\"/></figure>","tt-8j-aileron-lowering-on-locking":"<p><strong>Purpose</strong>: to lower the spoiler after the doors have been closed centrally.  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port.<br/><br/><strong></strong> 2 – Turn on the ignition and launch the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>46 – Central Conv</strong>.”</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>,” then click on “<strong>Long Coding Helper</strong>.”<br/><br/><strong>5</strong> – Select <em>Byte <strong>13</strong>: </em><br/><em>internal Bit <strong>7</strong>: Uncheck “Rear Spoiler Comfort Lowering via Door Lock active”</em> <em>to disable it</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8P0-907-063-B_Module09_Byte13-b06cb7b1.webp\"/></figure>","tt-8j-automatic-door-locks":"<p><strong>Purpose:</strong> to set automatic door locking from 15km/h.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 04</strong></p>\n<p><em>Set the value to <strong>1</strong></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Verrouillage-automatique-des-portieres_vw-auto-loc-ce03b1da.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>If the adaptation channel is not activated.</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>4</strong>: Check “Auto-Lock (automatic locking from 15 km/h)”. </em> </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Verrouillage-automatique-des-portieres-1K0_Module4-be0b33ff.webp\"/></figure>","tt-8j-automatic-door-unlocking":"<p><strong>Purpose:</strong> to set automatic door unlocking when the ignition key is removed.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Canal 05</strong></p>\n<p><em>Set the value to <strong>1</strong></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw-door-unlock-798a1163.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong><em>If the adaptation channel is not activated.</em></strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte<strong> 0</strong>: </em><br/><em>Bit <strong>3</strong>: Check “Auto-Unlock (unlocking after removing key from ignition)”. </em> </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Verrouillage-automatique-des-portieres-1K0_Module4-be0b33ff.webp\"/></figure>","tt-8j-aux-in-socket-activation-retrofit":"<p><strong>Purpose </strong>: to activate the AUX-IN input. After installing the jack plug on the car radio connector or a Bluetooth kit (RNS-E or Generation II+ Concert, Chorus and Symphony), you can select AUX-IN in Source. For a BT module, if you have the AMI option, deactivate it.   (Retrofit)</p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 (For RNS-E !) :</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“37 – Navigation</strong>” .<br/><br/><strong>4 </strong>– Click on<strong>“Codage- 07</strong>”.</p>\n<p><strong>5</strong> – Modify the penultimate digit by adding <strong>4</strong>(e.g. replace <strong>xxxxx1x</strong>with <strong>xxxxx5x</strong>). </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_stg37_navi_codierung_auxin-f8795b14.webp\"/></figure>\n<hr/>\n<p><strong>Line 2 (For Generation II+ Concert, Chorus and Symphony</strong>)<strong>:</strong><br/><br/> 3 – Click on ” <strong>Select</strong> ” then click on<strong>“56 – Radio</strong>” .<br/><br/> 4<strong>– </strong>Click on<strong>“Codage- 07</strong>“.  </p>\n<p>5 – Modify the second digit by adding <strong>+4</strong> (0<strong>?</strong>x0xxx): <strong><br/><br/>+1 = Analog input (AUX)</strong><br/>+2 = Multifunction steering wheel<br/>+4 = Telephone</p>","tt-8j-change-odb-language":"<p><strong>Purpose </strong>: Selects the language used in the on-board computer.  </p>\n<p><strong>(Modification only possible on Mid/High range models)</strong> </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 04</strong></p>\n<p><em>Change the value according to the desired language</em></p>\n<p><em>00001 – German</em><br/><em>00002 – English</em><br/><em>00003 – French</em><br/><em>00004 – Italian</em><br/><em>00005 – Spanish</em><br/><em>00006 – Portuguese / Brazilian</em></p>","tt-8j-comfort-turn-signal":"<p><strong>Purpose:</strong> to activate and set the number of flashes for the “Comfort flashing” option.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4 </strong>– Click on<strong>“Coding – 07</strong>”.</p>\n<p><strong>5 </strong>– Select Byte <strong>2</strong>,  </p>\n<p>Bit <strong>1</strong>: check<strong>“Comfort Turn Signal”.</strong> </p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>09 – Cent. Elect.</strong>“<br/><br/><strong>4 – </strong> Click “<strong>Adaptation – 10</strong>.”</p>\n<p><strong>5 </strong>– Select<strong>“Comfort Turn Signal”</strong> from the drop-down list</p>\n<p>Choose a value between 1 and 5 for the number of flashes</p>","tt-8j-corner-lights-activation":"<p><strong>Purpose</strong>: to activate cornering lights with fog lamps.  </p>\n<p><em><strong>Modification only possible for vehicles with a 30-byte module.</strong></em> </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>23</strong>: </em><br/><em>Bit <strong>2</strong>: Check “Internal Turn Light Control Algorithm active”.</em><br/><em>Bit <strong>3-4</strong>: Select “08 Turn Lights via fog lights” from the drop-down list</em></p>","tt-8j-correction-of-odb-consumption-display":"<p><strong>Purpose</strong>: to correct the fuel consumption display on the on-board computer.  </p>\n<p><strong>Modification only possible on Mid/High range models</strong>. <br/><em>Note: modifications affect the display of instantaneous consumption, average consumption and fuel quantity.</em></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on <strong>“17 – Instruments”</strong>. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation- 10</strong>”.</p>\n<p><strong>5</strong> – Select <strong>Channel 03</strong> <em>“Consumption Correction”.</em></p>\n<p><em>Adjust consumption correction factor between 85% and 115%.</em> <em>(base value: 100)</em></p>\n<p><em>Example 1: Calculation based on volume per distance (e.g. l/100 km): DIS: 9.3 l/100 km. Actual: 9.8 l/100 km. (100, 9,8 / 9,73 ? 105,38) Channel 3 will be changed from 100 to 105 <br/>Example 2: Calculation based on volume distance (e.g. MPG is: DIS: 23 MPG. Actual: 24 MPG. (100, 23/24 and 95.83) Channel 3 will be changed from 100 to 96</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/correction-consommation-odb-d51db18e.webp\"/></figure>","tt-8j-deactivate-aileron":"<p><strong>Purpose</strong>: to disable spoiler operation. If you code the spoiler deployed or closed, it will be locked in the position after coding! Perfect for mounting a fixed tuning spoiler.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>46 – Central Conv</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/> 5 – Choose <em>Byte <strong>10</strong>: </em><br/><em>Bit <strong>3</strong>: Uncheck “Rear Spoiler Installed”.</em></p>","tt-8j-deactivate-automatic-aileron-folding":"<p><strong>Purpose</strong>: to deactivate automatic spoiler folding when the spoiler has been deployed manually.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>46 – Central Conv</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/> 5 – Choose <em>Byte <strong>13</strong>: </em><br/><em>Bit <strong>6</strong>: Uncheck “Rear Spoiler Automatic Lowering after Manual Raising inactive”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8P0-907-063-B_Module09_Byte13-b06cb7b1.webp\"/></figure>","tt-8j-deactivate-brake-pad-warning-light":"<p><strong>Purpose</strong>: Allows you to disable the brake pad wear warning light on the OBD (On-Board Diagnostics) system, for example, for brake pads without a sensor or if the sensor is malfunctioning / Brake Pad Warning Light Deactivation. </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong></strong> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>17 – Instruments.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – <em>The third and fourth digits of the code (xx<strong>??</strong>x0x) are used to change the settings for the Instrument module. To turn off the windshield washer light, subtract <strong>1</strong> from these digits. </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-Golf5-2c5d8d07.webp\"/></figure>\n<p>In the example above, the initial code (with the windshield washer light on) is: <strong>0023103</strong></p>\n<p>To turn off the windshield washer light, simply recode it as follows: <strong>0022103 </strong><em>(23 – 01 = 22)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant-frein-d4619ec9.gif\"/></figure>","tt-8j-deactivate-windshield-washer-indicator":"<p><strong>Purpose</strong>: deactivates the windshield washer indicator on the ODB (on-board computer, for TT phase 1 only).  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>17 – Instruments</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Coding 07</strong>”.</p>\n<p><strong>5</strong> –  <em>The third and fourth coding digits (xx<strong>??</strong>x0x) are used to modify Instrument module options. To remove the ice-washer indicator, subtract <strong>4</strong> from these digits. </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-Golf5-2c5d8d07.webp\"/></figure>\n<p>In the example above, the initial coding (with washer indicator) is: <strong>0025103</strong></p>\n<p>To remove the windscreen washer indicator, simply recode as follows: <strong>0021103 </strong><em>(25 – 04 = 21)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/laveglaceaudia38p-d44c3cb7.webp\"/></figure>","tt-8j-delete-belt-alarm":"<p><strong>Purpose</strong>: To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>17 – Instruments</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Coding 07</strong>”.</p>\n<p><strong>5</strong> –  <em>The third and fourth coding digits (xx<strong>??</strong>x0x) are used to modify Instrument module options. To suppress the belt alarm, subtract <strong>2</strong> from these digits. </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-Golf5-2c5d8d07.webp\"/></figure>\n<p>In the example above, the initial coding (with belt alarm) is: <strong>0023103</strong></p>\n<p>To delete the belt alarm, simply recode as follows: <strong>0021103 </strong><em>(23 – 02 = 21)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","tt-8j-display-the-speed-on-the-audi-concert-ii":"<p><strong>Purpose:</strong> Adds a “Driving School” view to the Audi Concert II+ radio that displays your speed (also ideal for supervised driving) <br/><br/><br/><strong>Instructions:</strong> <br/><strong>1</strong> – With the engine off and the ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>56 – Radio</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>Channel 2</strong>” “Driving School Function/Time Display”<br/><br/><strong>7</strong> – Set the value to <strong>1</strong>.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/RCD300_Module56_Channel02-3c0994f0.webp\"/></figure>\n<p>To activate the function, select SETUP -&gt; Speed -&gt; On</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_concert_2_plus-444b7cdf.webp\"/></figure>","tt-8j-door-lock-unlock-confirmation-beep":"<p><strong>Purpose: </strong>Enables confirmation of vehicle locking/unlocking with beeps (alarm)  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“46 – Central Conv.</strong></p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><strong>6 </strong>– Select <em>Byte <strong>8</strong>: </em><br/><em>Bit <strong>1</strong>: Check “Unlocking Confirmation (Horn) via Door Locks”</em><br/><em>Bit <strong>3</strong>: Check “Unlocking Confirmation (Horn) via Remote Control </em>”.  </p>\n<p>Then<em>byte <strong>9</strong>: </em><br/><em>Bit <strong>1</strong>: Check “Locking Confirmation (Horn) via Door Locks”</em><br/><em>Bit <strong>3</strong>: Check “Locking Confirmation (Horn) via Remote Control </em>”.  </p>","tt-8j-flash-mode-lights-during-emergency-braking":"<p><strong>Purpose</strong>: activates brake lights in flash mode during emergency braking.  </p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>17</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Emergency Brake Flash Light active”.</em></p>","tt-8j-modify-power-steering-hardness":"<p><strong>Purpose </strong>: to adjust the hardness of the power steering for a softer or harder steering wheel.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“44 – Direction assistée” / “44-steering assist.</strong><br/><br/><strong>4 </strong>– Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>5 – </strong>Select<strong> Channel 1 </strong>, <em>set a value between<strong> 1</strong> and <strong>15</strong> depending on your hardness preference</em>.</p>\n<p><strong>Or Line 2: (If channel 1 is unavailable)</strong>:<br/><br/> 3 – Click on<strong>“Select</strong>” then click on<strong>“44 – Direction assistée” / “44-steering assist.”</strong><br/><br/> 4<strong>– </strong> Click on<strong>“Coding – 07</strong>”.</p>\n<p><strong>5 – </strong>Select :</p>\n<ul>\n<li>xxx1x for smooth steering</li>\n<li>xxx2x for sports management</li>\n<li>xxx3x for hard steering</li>\n<li>xxx4x for harder steering</li>\n<li>xxx5x for very hard steering</li>\n</ul>","tt-8j-one-touch-window-closing":"<p><strong>Purpose</strong>: to activate closing and opening of the windows and sunroof with the remote control <strong>WITHOUT </strong>remaining pressed until the windows are completely closed.  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition turned off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port.<br/><br/><strong></strong> 2 – Turn on the ignition and launch the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>46 – Central Conv.”</strong></p>\n<p><strong>4</strong> – Click ” <strong>Encoding 07</strong>,” then “Long Coding Helper”</p>\n<p><strong>5 –</strong> <em>Byte 6: </em><br/><em>Bit 6: Check “Comfort Function Automatic Closing”</em></p>\n<ul>\n<li>Uncheck “Comfort function power windows/sunroof via remote control inactive”.</li>\n<li>Check “Comfort opening power windows via remote control active”.</li>\n<li>Check “Comfort closing power windows via remote control active”.</li>\n<li>Check “Closing sunroof via remote control active” (sunroof)</li>\n</ul>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/ComfortConv-byte6-9f2c129f.webp\"/></figure>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>46 – Comfort Module.”</strong><br/><br/><strong>4 – </strong>Click “ <strong>Adaptation – 10”</strong> </p>\n<p><strong>Channel 17</strong> (Comfort function)</p>\n<p><em>Set value to 1</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_0944-1024x741-ec4d5180.webp\"/></figure>\n<p><em>Pressing the remote control’s close button for 3 seconds will first lock the doors and then close the windows, without having to keep the button pressed until they are fully closed</em>.</p>\n<p>If you don’t have this box on your calculator, put this:<br/>module 46, long coding and on the:<br/>Byte 03: 40<br/>Byte 04: 3F<br/>Byte 05: 3F</p>","tt-8j-rear-lights-activated-with-daytime-running-lights-drl":"<p><strong>Purpose:</strong> Enables the rear lights to turn on when the daytime running lights (Scandinavian DRL) are activated. <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><br/><strong>Line 1 (</strong><strong>until 2008) :</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on <strong>“Coding – 07</strong>“.</p>\n<p><strong>5 –</strong> Byte <strong>1</strong> Set bit <strong>4</strong> – daytime running lights (North America) active</p>\n<p><strong>Line 2 (2009–2011):</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>09 – Cent. Elect.</strong>“<br/><br/><strong>4</strong> – Click <strong>“Coding – 07</strong>.”</p>\n<p><strong>5 –</strong> Byte <strong>26</strong> Set bit <strong>1</strong>, bit <strong>3</strong> and bit <strong>5</strong></p>\n<p>So the following behavior :</p>\n<ul>\n<li>DRL: LEDs on at 100% brightness and tail lights off</li>\n<li>Parking lights on : LEDs on at 100% brightness and tail lights on</li>\n<li>Low beam on : LEDs + xenons on and tail lights on</li>\n<li>Flashing: no LED variation</li>\n</ul>","tt-8j-activate-daytime-running-lights-with-fog-lamps-drl":"<p><strong>Purpose</strong>: Allows fog lights to be used as daytime running lights.  </p>\n<p><strong>Procedure</strong>: <br/><strong>1</strong> – With the engine off and the ignition off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.<br/><br/><strong>2</strong> – Turn on the ignition, then launch the VCDS program.<br/><br/><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><strong>6 –</strong> <em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>4</strong>: Check “Daytime Running Lights (North America)”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/scandinavie_194-c7df4fa8.webp\"/></figure>\n<p><strong>7 – </strong> <em>Byte <strong>17: </strong> </em><br/><em>Bit <strong>4</strong>: Check “Daytime Running Light with dimmed Low Beam” (or “Daytime Running Light via Fog Lights,” depending on your version of VCDS)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/ab_975-e7b60077.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/veilleusejour3-c639151f.webp\"/></figure>\n<p><strong>8-</strong> Adjusting the fog light intensity (from 1% to 99%)</p>\n<p><em>Byte <strong>20</strong>: </em><br/><em>Change the value in the <strong>Dec</strong> box</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/VagComByte20-adce5646.webp\"/></figure>"};
